CREATE OR REPLACE FUNCTION private.admin_report_detail (
  actor            uuid,
  actor_session    uuid,
  report           bigint,
  before_report_id bigint DEFAULT NULL::bigint
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare r private.reports%rowtype; result jsonb;
begin
  perform private.assert_moderator(actor, actor_session);
  select * into r from private.reports where id = report;
  if not found then raise exception 'report_not_found' using errcode = 'P0002'; end if;
  select jsonb_build_object('report',to_jsonb(r) || jsonb_build_object('id',r.id::text,'post_id',r.post_id::text,'comment_id',r.comment_id::text),
    'related_reports',coalesce((select jsonb_agg(to_jsonb(page) || jsonb_build_object('id',page.id::text,'post_id',page.post_id::text,'comment_id',page.comment_id::text) order by page.id desc)
      from (select * from private.reports other where other.target_type=r.target_type and
        (other.post_id=r.post_id or other.comment_id=r.comment_id) and (before_report_id is null or other.id<before_report_id) order by other.id desc limit 50) page),'[]'::jsonb),
    'post',case when p.id is null then null else to_jsonb(p) || jsonb_build_object('id',p.id::text) end,
    'comment',case when c.id is null then null else to_jsonb(c) || jsonb_build_object('id',c.id::text,'post_id',c.post_id::text,'parent_id',c.parent_id::text) end,
    -- 신고된 댓글이 답글이면 원 댓글을 함께 보여 준다.
    'parent_comment',case when parent_comment.id is null then null else jsonb_build_object('id',parent_comment.id::text,
      'content',parent_comment.content,'deleted_at',parent_comment.deleted_at,'hidden_at',parent_comment.hidden_at,
      'created_at',parent_comment.created_at) end,
    'products',coalesce((select jsonb_agg(to_jsonb(pp) || jsonb_build_object('post_id',pp.post_id::text) order by pp.position) from private.post_products pp where pp.post_id=p.id),'[]'::jsonb),
    'author',case when profile.id is null then null else jsonb_build_object('id',profile.id,'status',profile.status,'restricted_until',profile.restricted_until) end,
    'sanctions',coalesce((select jsonb_agg(to_jsonb(s) || jsonb_build_object('id',s.id::text,'action_id',s.action_id::text) order by s.id desc)
      from private.user_sanctions s where s.user_id = r.reported_user_id),'[]'::jsonb),
    'actions',coalesce((select jsonb_agg(to_jsonb(a) || jsonb_build_object('id',a.id::text) order by a.id desc)
      from private.admin_actions a where a.report_id = r.id or
        (a.target_type=r.target_type::text and a.target_id=coalesce(r.post_id,r.comment_id)::text) or
        (a.target_type='user' and a.target_id=r.reported_user_id::text)),'[]'::jsonb)
  ) into result from (select 1) seed
    left join private.comments c on c.id=r.comment_id
    left join private.comments parent_comment on parent_comment.id=c.parent_id
    left join private.posts p on p.id=coalesce(r.post_id,c.post_id)
    left join public.profiles profile on profile.id=r.reported_user_id;
  insert into private.admin_access_logs(admin_id,report_id,session_ip,subject_ids)
    values(actor,report,(select s.ip from auth.sessions s where s.id=actor_session and s.user_id=actor),
      (select coalesce(array_agg(distinct subject_id) filter(where subject_id is not null),'{}'::uuid[])
        from (
          select r.reported_user_id as subject_id
          union all select (item->>'reporter_id')::uuid from jsonb_array_elements(result->'related_reports') item
        ) subjects));
  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.community_comment_json (
  target_comment_id bigint
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select jsonb_build_object(
    'id', c.id::text, 'created_at', c.created_at,
    'content', case when c.author_id is null then null else c.content end,
    'is_post_author', c.author_id = p.author_id,
    'is_mine', c.author_id = (select auth.uid()), 'is_withdrawn', c.author_id is null,
    'anon_number', a.number, 'author_nickname', author.nickname,
    'is_operator', operator.id is not null,
    'vote_choice', vote.choice,
    'parent_id', c.parent_id::text
  ) from private.comments c join private.posts p on p.id = c.post_id
  left join public.profiles author on author.id = c.author_id
  left join private.post_anon_numbers a on a.post_id = c.post_id and a.user_id = c.author_id
  left join private.admin_users operator on operator.id = c.author_id and operator.disabled_at is null
  left join private.vote_responses vote on p.type = 'vote' and vote.post_id = c.post_id and vote.user_id = c.author_id
  where c.id = target_comment_id;
$function$;

CREATE OR REPLACE FUNCTION private.community_comment_listed (
  target_comment_id bigint
)
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select exists (
    select 1 from private.comments c
    left join private.comments parent on parent.id = c.parent_id
    where c.id = target_comment_id and c.deleted_at is null and c.hidden_at is null
      and private.community_author_visible(c.author_id) and private.community_content_visible('comment', c.id)
      and (c.parent_id is null or (parent.deleted_at is null and parent.hidden_at is null
        and private.community_author_visible(parent.author_id) and private.community_content_visible('comment', parent.id)))
  );
$function$;

CREATE OR REPLACE FUNCTION private.community_post_json (
  target_post_id bigint,
  is_preview     boolean
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select case when is_preview then jsonb_build_object(
    'id', p.id::text, 'type', p.type, 'created_at', p.created_at,
    'content', split_part(replace(p.content, E'\r', ''), E'\n', 1),
    'items', coalesce((select jsonb_agg(jsonb_build_object(
      'position', i.position, 'image_url', i.image_url) order by i.position)
      from private.post_products i where i.post_id = p.id), '[]'::jsonb)
  ) else jsonb_build_object(
    'id', p.id::text, 'type', p.type, 'created_at', p.created_at, 'ends_at', p.ends_at,
    'server_now', now(), 'content', p.content, 'is_mine', p.author_id = (select auth.uid()),
    'author_nickname', author.nickname,
    'notice', case when p.notice_title is not null then jsonb_build_object(
      'title',p.notice_title,'comments_closed',p.notice_comments_closed) else null end,
    'items', coalesce((select jsonb_agg(jsonb_build_object(
      'position', i.position, 'name', i.name, 'brand', i.brand, 'price', i.price,
      'url', i.url, 'image_url', i.image_url) order by i.position)
      from private.post_products i where i.post_id = p.id), '[]'::jsonb),
    'like_count', (select count(*) from private.post_likes l where l.post_id = p.id),
    'is_liked', exists(select 1 from private.post_likes l where l.post_id = p.id and l.user_id = (select auth.uid())),
    'comment_count', (select count(*) from private.comments c where c.post_id = p.id
      and private.community_comment_listed(c.id)),
    'my_choice', (select v.choice from private.vote_responses v where v.post_id = p.id and v.user_id = (select auth.uid())),
    'buy_count', case when p.type = 'vote' and (p.author_id = (select auth.uid()) or p.ends_at <= now() or
      exists(select 1 from private.vote_responses v where v.post_id = p.id and v.user_id = (select auth.uid())))
      then (select count(*) from private.vote_responses v where v.post_id = p.id and v.choice = 'buy') else null end,
    'not_count', case when p.type = 'vote' and (p.author_id = (select auth.uid()) or p.ends_at <= now() or
      exists(select 1 from private.vote_responses v where v.post_id = p.id and v.user_id = (select auth.uid())))
      then (select count(*) from private.vote_responses v where v.post_id = p.id and v.choice = 'not') else null end
  ) end
  from private.posts p join public.profiles author on author.id = p.author_id
  where p.id = target_post_id;
$function$;

CREATE OR REPLACE FUNCTION private.create_comment (
  target_post_id    bigint,
  comment_content   text,
  request_id        uuid,
  parent_comment_id bigint DEFAULT NULL::bigint
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  target private.posts%rowtype;
  viewer_id uuid := (select auth.uid());
  existing private.comments%rowtype;
  parent private.comments%rowtype;
  clean_content text;
  anon_number integer;
  saved_id bigint;
begin
  -- 글 잠금을 먼저 잡아 원 댓글 삭제와 답글 등록을 줄 세운다.
  target := private.lock_community_post_for_write(target_post_id);
  if target.notice_title is not null and target.notice_comments_closed then
    raise exception 'notice_comments_closed' using errcode='P0001';
  end if;
  if request_id is null then raise exception 'invalid_request_id' using errcode = '22023'; end if;
  select * into existing from private.comments where author_id = viewer_id and creation_request_id = request_id;
  if found then
    if existing.post_id <> target.id or existing.parent_id is distinct from parent_comment_id then
      raise exception 'invalid_request_id' using errcode = '22023';
    end if;
    if existing.deleted_at is not null or existing.hidden_at is not null then
      raise exception 'comment_not_found' using errcode = '42501';
    end if;
    return private.community_comment_json(existing.id);
  end if;
  if parent_comment_id is not null then
    select * into parent from private.comments where id = parent_comment_id and post_id = target.id;
    if not found or not private.community_comment_listed(parent.id) then
      raise exception 'comment_not_found' using errcode = '42501';
    end if;
    if parent.parent_id is not null then raise exception 'invalid_reply_target' using errcode = '22023'; end if;
  end if;
  clean_content := private.normalize_comment_content(comment_content);
  if viewer_id <> target.author_id then
    select number into anon_number from private.post_anon_numbers where post_id = target.id and user_id = viewer_id;
    if anon_number is null then
      update private.posts set next_anon_number = next_anon_number + 1 where id = target.id
      returning next_anon_number - 1 into anon_number;
      insert into private.post_anon_numbers(post_id, user_id, number) values (target.id, viewer_id, anon_number);
    end if;
  end if;
  insert into private.comments(post_id, parent_id, author_id, content, creation_request_id)
  values (target.id, parent_comment_id, viewer_id, clean_content, request_id) returning id into saved_id;
  return private.community_comment_json(saved_id);
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_community_comments (
  target_post_id   bigint,
  after_created_at timestamp with time zone DEFAULT NULL::timestamp WITH time zone,
  after_id         bigint                   DEFAULT NULL::bigint
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if private.get_community_post(target_post_id) is null or exists (select 1 from private.posts p
    where p.id=target_post_id and p.notice_title is not null and p.notice_comments_closed) then return '[]'::jsonb; end if;
  if (after_created_at is null) <> (after_id is null) then
    raise exception 'invalid_comment_cursor' using errcode = '22023';
  end if;
  return (
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', c.id::text, 'created_at', c.created_at,
      'content', case when c.author_id is null then null else c.content end,
      'is_post_author', c.author_id = p.author_id,
      'is_mine', c.author_id = (select auth.uid()), 'is_withdrawn', c.author_id is null,
      'anon_number', a.number, 'author_nickname', author.nickname,
      'is_operator', operator.id is not null,
      'vote_choice', vote.choice,
      'parent_id', null,
      -- 커서는 원 댓글 기준이라 답글은 원 댓글 안에 넣는다. 이전 앱은 replies를 무시한다.
      'replies', coalesce((select jsonb_agg(private.community_comment_json(r.id) order by r.created_at, r.id)
        from private.comments r where r.parent_id = c.id and private.community_comment_listed(r.id)), '[]'::jsonb)
    ) order by c.created_at, c.id), '[]'::jsonb)
    from (
      select c.* from private.comments c
      where c.post_id = target_post_id and c.parent_id is null and private.community_comment_listed(c.id)
        and (after_created_at is null or (c.created_at, c.id) > (after_created_at, after_id))
      order by c.created_at, c.id limit 20
    ) c
    join private.posts p on p.id = c.post_id
    left join public.profiles author on author.id = c.author_id
    left join private.post_anon_numbers a on a.post_id = c.post_id and a.user_id = c.author_id
    left join private.admin_users operator on operator.id = c.author_id and operator.disabled_at is null
    left join private.vote_responses vote on p.type = 'vote' and vote.post_id = c.post_id and vote.user_id = c.author_id
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.notify_post_commented()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  target private.posts%rowtype;
  actor_nickname text;
  recipient uuid;
begin
  select * into target from private.posts where id = new.post_id;
  if target.deleted_at is not null or target.hidden_at is not null or new.author_id is null or
     (new.parent_id is null and (target.type <> 'post' or target.notice_title is not null)) then
    return new;
  end if;
  if new.parent_id is null then recipient := target.author_id;
  else select author_id into recipient from private.comments where id = new.parent_id;
  end if;
  if recipient is null or recipient = new.author_id or
     not private.notification_actor_visible(recipient, new.author_id) then
    return new;
  end if;
  select nickname into actor_nickname from public.profiles where id = new.author_id;
  insert into private.notifications(recipient_id, type, post_id, actor_id, title, body, event_key)
  values (recipient, 'post_commented', target.id, new.author_id,
          case when new.parent_id is null then '내 게시글에 댓글이 달렸어요.' else '내 댓글에 답글이 달렸어요.' end,
          coalesce(actor_nickname, '사용자') || ': ' || private.notification_text(new.content),
          case when new.parent_id is null then 'comment:' else 'reply:' end || new.id)
  on conflict (event_key) do nothing;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.push_notification_allowed (
  notification_id bigint,
  token_id        bigint
)
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select exists (
    select 1 from private.notifications n
    join private.posts p on p.id = n.post_id
    join public.profiles u on u.id = n.recipient_id
    join public.push_tokens t on t.id = token_id and t.user_id = n.recipient_id
    left join private.notification_settings s on s.user_id = n.recipient_id
    where n.id = notification_id and n.created_at > now() - interval '24 hours'
      and u.status <> 'suspended' and coalesce(s.push_enabled, true)
      and p.deleted_at is null and p.hidden_at is null
      and (n.type <> 'post_commented' or exists (
        select 1 from private.comments c
        where c.post_id = n.post_id and n.event_key in ('comment:' || c.id, 'reply:' || c.id)
          and c.deleted_at is null
      ))
      and (n.actor_id is null or private.notification_actor_visible(n.recipient_id, n.actor_id))
  );
$function$;

CREATE OR REPLACE FUNCTION private.report_community_content (
  content_type  text,
  target_id     bigint,
  report_reason text,
  report_detail text   DEFAULT NULL::text
)
  RETURNS text
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  viewer uuid := (select auth.uid());
  parent private.posts%rowtype;
  comment private.comments%rowtype;
  author uuid;
  saved_id bigint;
  clean_detail text := nullif(normalize(btrim(report_detail), NFC), '');
  parent_id bigint;
begin
  perform private.assert_can_report_community();
  if content_type is null or content_type not in ('post','comment') or target_id is null or target_id <= 0 then
    raise exception 'invalid_report_target' using errcode = '22023';
  end if;
  if report_reason is null or report_reason not in ('abuse','spam','inappropriate','other') or
    (report_reason <> 'other' and clean_detail is not null) or private.char_count(clean_detail) > 50 then
    raise exception 'invalid_report_reason' using errcode = '22023';
  end if;
  -- 동일 신고 재시도는 원래 사유·Snapshot을 보존한다. 동시 요청도 한 건만 생성한다.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(viewer::text || ':' || content_type || ':' || target_id::text, 0));
  select r.id,r.reported_user_id into saved_id,author from private.reports r where r.reporter_id = viewer
    and ((content_type = 'post' and r.post_id = target_id) or (content_type = 'comment' and r.comment_id = target_id));
  if saved_id is not null then
    if exists(select 1 from private.admin_users a where a.id=author and a.disabled_at is null) then
      raise exception 'operator_content_protected' using errcode='42501';
    end if;
    return saved_id::text;
  end if;
  if content_type = 'post' then parent_id := target_id;
  else
    select c.post_id into parent_id from private.comments c where c.id = target_id;
  end if;
  -- 기존 댓글 수정·삭제와 같은 부모 → 댓글 잠금 순서로 Snapshot 경합을 막는다.
  select * into parent from private.posts where id = parent_id for update;
  if not found or parent.deleted_at is not null or parent.hidden_at is not null or
    not private.community_author_visible(parent.author_id) or
    not private.community_content_visible('post', parent.id) then
    raise exception 'report_target_not_found' using errcode = '42501';
  end if;
  if content_type = 'comment' then
    select * into comment from private.comments where id = target_id for update;
    -- 원 댓글이 빠져 목록에 안 보이는 답글도 신고할 수 없다.
    if not found or comment.author_id is null or not private.community_comment_listed(comment.id) then
      raise exception 'report_target_not_found' using errcode = '42501';
    end if;
    author := comment.author_id;
  else author := parent.author_id;
  end if;
  if author = viewer then raise exception 'own_report' using errcode = '42501'; end if;
  if exists(select 1 from private.admin_users a where a.id=author and a.disabled_at is null) then
    raise exception 'operator_content_protected' using errcode='42501';
  end if;
  insert into private.reports(reporter_id, target_type, post_id, comment_id, reported_user_id, reason, detail, reported_content)
  values (viewer, content_type::public.report_target,
    case when content_type = 'post' then target_id end,
    case when content_type = 'comment' then target_id end, author, report_reason::public.report_reason,
    clean_detail, case when content_type = 'comment' then comment.content end)
  returning id into saved_id;
  return saved_id::text;
end;
$function$;

CREATE OR REPLACE FUNCTION public.create_comment (
  target_post_id    bigint,
  comment_content   text,
  request_id        uuid,
  parent_comment_id bigint DEFAULT NULL::bigint
)
  RETURNS jsonb
  LANGUAGE sql
  SET search_path TO ''
  AS $function$
  select private.create_comment(target_post_id, comment_content, request_id, parent_comment_id);
$function$;

